/* Personal photographs stay in this private Site; chapter progress is the album. */
const ALBUM=[
 {id:'market',src:'assets/memory-mirror.jpg',title:'镜头里的我们',line:'和你一起，普通的镜子也能留下喜欢的画面。',position:'50% 58%'},
 {id:'memory',src:MEMORY_PHOTO,title:'琉璃阁的那一天',line:'十一，我们去了北京北海公园琉璃阁。那天很开心。',position:'50% 73%'},
 {id:'water',src:'assets/memory-together.jpg',title:'在你身边',line:'我喜欢的，是能和你待在一起的这些小片刻。',position:'50% 53%'},
 {id:'greenhouse',src:'assets/memory-flowers.jpg',title:'把喜欢捧在怀里',line:'这一张，想放在回家就能看见的地方。',position:'50% 44%'},
 {id:'post',src:'assets/memory-close.jpg',title:'再靠近一点',line:'走了这么远，最想抵达的还是你身边。',position:'50% 47%'}
];
let albumReward=null,albumFireFrame=0,albumHolds=new Set(),albumIgnited=false;
const albumOwned=()=>ALBUM.filter(p=>campaign.done.includes(p.id));
function albumState(){return campaign.album||(campaign.album={hung:[],celebrated:false})}
const albumOriginalFinish=cpFinish;
cpFinish=function(id){const first=!campaign.done.includes(id);albumOriginalFinish(id);if(first&&ALBUM.some(p=>p.id===id)){albumReward=id;albumShowReward()}};
function albumImage(p,cls=''){return `<img class="${cls}" src="${p.src}" alt="${p.title}" style="object-position:${p.position}" decoding="async">`}
function albumShowReward(){const p=ALBUM.find(p=>p.id===albumReward);if(!p)return;cpFrame('我们又找回了一张合照。','这张回忆已经收好。等回到小屋，一起把它挂起来。',`<div class="album-reward"><figure class="album-polaroid">${albumImage(p)}<figcaption>${p.title}</figcaption></figure><div><div class="eyebrow">A MOMENT OF US · ${albumOwned().length} / 5</div><h3>通关的奖励，<br>是和你在一起的时刻。</h3><p>${p.line}</p><small>点开照片可以看原图 · 回忆册会保存在这台设备</small></div></div>`,cpButton('albumKeep','收进回忆册，继续旅程 →','primary'));document.querySelector('.album-polaroid').onclick=()=>albumEnlarge(p);document.querySelector('#albumKeep').onclick=()=>{albumReward=null;cpMap()}}
function albumEnlarge(p){const d=document.createElement('dialog');d.className='album-dialog';d.innerHTML=`<button aria-label="关闭照片">关闭 ×</button>${albumImage(p)}<p>${p.title}</p>`;document.body.append(d);d.querySelector('button').onclick=()=>d.close();d.onclick=e=>{if(e.target===d)d.close()};d.onclose=()=>d.remove();d.showModal()}
function albumInventory(){const owned=albumOwned();const d=document.createElement('dialog');d.className='album-dialog album-book';d.innerHTML=`<button class="album-close" aria-label="关闭回忆册">关闭 ×</button><h2>口袋里的回忆 · ${owned.length}/5</h2><p>每完成一章，一张合照就会跟着我们回家。</p><div class="album-grid">${ALBUM.map(p=>`<button class="album-thumb ${owned.includes(p)?'owned':''}" data-album-photo="${p.id}" ${owned.includes(p)?'':'disabled'}>${owned.includes(p)?albumImage(p):'<span>✧</span>'}<strong>${owned.includes(p)?p.title:'还有一段路，等我们一起走'}</strong></button>`).join('')}</div>`;document.body.append(d);d.querySelector('.album-close').onclick=()=>d.close();d.onclose=()=>d.remove();d.onclick=e=>{if(e.target===d)d.close()};d.querySelectorAll('[data-album-photo]').forEach(b=>b.onclick=()=>albumEnlarge(ALBUM.find(p=>p.id===b.dataset.albumPhoto)));d.showModal()}
function albumHang(id){const a=albumState();if(!a.hung.includes(id)&&albumOwned().some(p=>p.id===id)){a.hung.push(id);chime();cpSave();render()}}
function albumHome(){const a=albumState(),owned=albumOwned(),ready=owned.length===5&&ALBUM.every(p=>a.hung.includes(p.id));cpFrame('终于，把我们的回忆带回家。','把口袋里的照片一张张挂好。这里以后也一直留着我们。',`<div class="album-room"><div class="album-wall"><div class="album-wall-label">OUR LITTLE HOME · 我们的小屋</div><div class="album-wall-grid">${ALBUM.map((p,i)=>`<button class="album-wall-frame ${a.hung.includes(p.id)?'hung':''}" data-hang="${p.id}" style="--tilt:${[-5,3,-2,4,-3][i]}deg" ${!owned.includes(p)?'disabled':''}>${a.hung.includes(p.id)?albumImage(p):`<span>${owned.includes(p)?'＋ 挂上这张合照':'✧ 还在旅途中'}</span>`}<small>${a.hung.includes(p.id)?p.title:'回忆 '+(i+1)}</small></button>`).join('')}</div><div class="album-shelf"></div><div class="album-room-pair"><svg viewBox="0 0 1000 130" aria-label="一起回到小屋的两个人"><defs>${daylightDefs}</defs>${character(460,63,true)+character(525,63,false)}</svg></div></div><div class="album-home-note"><span>✦</span><h3>${ready?'每一张照片，都是我们。':'小屋还在等这些回忆。'}</h3><p>${ready?'照片都挂好了。现在，给今晚留一场烟花吧。':`已经挂好 ${a.hung.length} / 5 张。点亮空相框，把合照放进去。`}</p>${ready?cpButton('albumFireworks',a.celebrated?'再看一场生日烟花 ✨':'一起去窗边，点亮烟花 ✨','primary'):''}<button id="albumOpenBook" class="control">翻开回忆册 · ${owned.length}/5</button><button id="gift" class="text" ${a.celebrated?'':'hidden'}>还有一件礼物，想交给你 →</button></div></div>`,cpButton('albumBack','回到小镇地图','text'));document.querySelectorAll('[data-hang]').forEach(b=>b.onclick=()=>a.hung.includes(b.dataset.hang)?albumEnlarge(ALBUM.find(p=>p.id===b.dataset.hang)):albumHang(b.dataset.hang));document.querySelector('#albumOpenBook').onclick=albumInventory;document.querySelector('#albumBack').onclick=cpMap;document.querySelector('#albumFireworks')?.addEventListener('click',albumFireworks);document.querySelector('#gift').onclick=albumGift}
function albumGift(){cpFrame('生日快乐，我最喜欢的人。','走完今晚的小路，还有一份现实里的礼物想交给你。',`<div class="album-gift"><span>🧴</span><h2>新的一岁，也一起。</h2><div class="letter">这套护肤品，是送给你的生日礼物。<br>想陪你开心，也想陪你好好照顾自己。<br><br>以后还有好多张合照，<br>好多段路，想和你一起慢慢收集。</div></div>`,cpButton('albumReturnHome','回到我们的照片小屋 ♡','primary'));document.querySelector('#albumReturnHome').onclick=render}
function albumStopFireworks(){cancelAnimationFrame(albumFireFrame);albumFireFrame=0;albumHolds.clear();albumIgnited=false}
function albumFireworks(){albumStopFireworks();const d=document.createElement('dialog');d.className='album-fireworks';d.innerHTML=`<canvas aria-label="生日星空烟花"></canvas><button class="album-fire-close">回到小屋 ×</button><div class="album-fire-copy"><div class="eyebrow">TONIGHT, FOR YOU</div><h2>这一整片星空，送给你。</h2><p id="albumFireStatus">两个人各按住一颗星，一起点亮生日烟花。</p></div><div class="album-fire-pair"><svg viewBox="0 0 1000 150"><defs>${daylightDefs}</defs>${character(465,90,true)+character(525,90,false)}</svg></div><div class="album-fire-keys"><button data-fire-key="a">我这边 · 按住 ✦</button><button data-fire-key="b">你这边 · 按住 ✦</button></div><div id="albumFireEnd" hidden><strong>生日快乐，和你在一起的每一天。</strong><button id="albumFireGift" class="primary">回到小屋，拆开生日礼物 →</button></div>`;document.body.append(d);d.showModal();d.querySelector('.album-fire-close').onclick=()=>d.close();d.onclose=()=>{albumStopFireworks();d.remove();render()};const status=d.querySelector('#albumFireStatus');const ignite=()=>{if(albumIgnited||albumHolds.size<2)return;albumIgnited=true;albumState().celebrated=true;cpSave();status.textContent='愿新的一岁，我们仍然牵着手，去看更多风景。';d.classList.add('ignited');d.querySelector('#albumFireEnd').hidden=false;chime(true)};
 d.querySelectorAll('[data-fire-key]').forEach(b=>{const down=e=>{e.preventDefault();if(e.pointerId!==undefined)b.setPointerCapture(e.pointerId);albumHolds.add(b.dataset.fireKey);b.classList.add('active');ignite()};const up=()=>{albumHolds.delete(b.dataset.fireKey);b.classList.remove('active')};b.onpointerdown=down;b.onpointerup=b.onpointercancel=b.onlostpointercapture=up;b.onkeydown=e=>{if(e.code==='Space'||e.code==='Enter')down(e)};b.onkeyup=up});d.querySelector('#albumFireGift').onclick=()=>{d.close();setTimeout(albumGift,0)};
 const canvas=d.querySelector('canvas'),ctx=canvas.getContext('2d'),particles=[],rockets=[];let last=0,nextRocket=0;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;function burst(x,y){const hue=Math.random()*360,count=reduced?24:90;for(let i=0;i<count;i++){const angle=i/count*Math.PI*2,v=1.2+Math.random()*3.6;particles.push({x,y,vx:Math.cos(angle)*v,vy:Math.sin(angle)*v,life:1,hue})}}function tick(t){if(!d.open||document.hidden){last=t;albumFireFrame=requestAnimationFrame(tick);return}const w=d.clientWidth,h=d.clientHeight,ratio=Math.min(devicePixelRatio||1,2);if(canvas.width!==Math.round(w*ratio)||canvas.height!==Math.round(h*ratio)){canvas.width=w*ratio;canvas.height=h*ratio;ctx.setTransform(ratio,0,0,ratio,0,0)}const dt=Math.min((t-last)/16.67||1,2);last=t;ctx.globalCompositeOperation='source-over';ctx.fillStyle='rgba(14,15,42,.22)';ctx.fillRect(0,0,w,h);ctx.globalCompositeOperation='lighter';if(albumIgnited&&t>nextRocket){rockets.push({x:w*(.15+Math.random()*.7),y:h,v:-6-Math.random()*3,target:h*(.13+Math.random()*.35),hue:Math.random()*360});nextRocket=t+(reduced?1800:650)}for(let i=rockets.length-1;i>=0;i--){const r=rockets[i];r.y+=r.v*dt;ctx.fillStyle=`hsl(${r.hue} 90% 75%)`;ctx.fillRect(r.x,r.y,2,13);if(r.y<r.target){burst(r.x,r.y);rockets.splice(i,1)}}for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=.025*dt;p.vx*=.992;p.life-=.009*dt;if(p.life<=0){particles.splice(i,1);continue}ctx.fillStyle=`hsla(${p.hue} 90% 76% / ${p.life})`;ctx.beginPath();ctx.arc(p.x,p.y,1.5,0,Math.PI*2);ctx.fill()}albumFireFrame=requestAnimationFrame(tick)}albumFireFrame=requestAnimationFrame(tick)
}
const albumBaseSave=cpSave;cpSave=function(){albumBaseSave()};
const albumBaseRestore=cpRestore;cpRestore=function(){const ok=albumBaseRestore();if(ok){try{const a=JSON.parse(localStorage.getItem(CP_KEY)).campaign.album;campaign.album={hung:Array.isArray(a?.hung)?[...new Set(a.hung.filter(id=>ALBUM.some(p=>p.id===id)&&campaign.done.includes(id)))]:[],celebrated:a?.celebrated===true,layout:a?.layout}}catch{}}return ok};
function albumIntro(){const intro=document.querySelector('.intro');if(!intro)return;intro.classList.add('album-intro');intro.querySelector('.copy').innerHTML=`<div class="eyebrow">A LITTLE WALK · 回忆收藏版</div><h1>今晚，和我把<br>回忆带回家。</h1><p>暮光小镇里，藏着我们走过的片刻。<br>一关一张合照，最后把它们挂进我们的小屋。</p><div class="album-intro-scene"><svg viewBox="0 0 480 150" aria-label="两个人在暮光小镇等待出发"><defs>${daylightDefs}</defs><circle cx="375" cy="32" r="22" fill="#f5dba0"/><path d="M20 133Q160 72 275 124T480 125V150H0Z" fill="#77617e"/><path d="M85 75h55v56H85Zm-8 0 36-28 36 28" fill="#9b8290"/><rect x="105" y="92" width="16" height="21" rx="3" fill="#f4d69b"/><g fill="#eed1a0"><circle cx="50" cy="30" r="2"/><circle cx="210" cy="22" r="2"/><circle cx="295" cy="54" r="2"/><circle cx="445" cy="48" r="2"/></g>${character(228,98,true)+character(282,98,false)}</svg></div><div class="album-intro-route"><span>五张回忆合照</span><i>·</i><span>双人星光桥</span><i>·</i><span>照片小屋与烟花</span></div>`;document.querySelector('#hint').textContent='回忆收藏版 · 暮光小镇 → 照片小屋';chapter.textContent='PROLOGUE · 回忆收藏版';intro.querySelector('.verify .eyebrow').textContent='出发之前 · 让我认出你';intro.querySelector('#verify').textContent='认出你啦，去暮光小镇 →'}
const albumBaseRender=render;render=function(){if(campaign.started&&!campaign.active&&!memory.active&&stage===5){albumHome();cpDecorate()}else albumBaseRender();if(stage===0&&!campaign.active&&!memory.active)albumIntro();const button=document.querySelector('#albumButton');button.hidden=!campaign.started;button.textContent=`回忆册 ${albumOwned().length}/5`;if(campaign.active==='map'){const desc=document.querySelector('.cp-heading p');if(desc)desc.textContent='回忆收藏版 · 每章一张合照，过桥后带回照片小屋，一起放生日烟花。'}};
const albumButton=document.createElement('button');albumButton.id='albumButton';albumButton.className='text';albumButton.onclick=albumInventory;document.querySelector('header').insertBefore(albumButton,document.querySelector('#restart'));
const albumBaseReset=reset;reset=function(){const u=new URL(location.href);u.searchParams.delete('chapter');u.searchParams.delete('fresh');history.replaceState(null,'',u.toString());document.querySelectorAll('.album-dialog,.album-fireworks').forEach(d=>d.close());albumStopFireworks();albumReward=null;albumBaseReset()};document.querySelector('#restart').onclick=reset;document.querySelector('#brand').onclick=e=>{e.preventDefault();reset()};window.addEventListener('blur',()=>{albumHolds.clear();document.querySelectorAll('[data-fire-key]').forEach(b=>b.classList.remove('active'))});
cpRestore();render();
